    const dots=s.points.map((p,pi)=>{
      const x=sx(p.x), y=sy(p.y);
      return `<circle cx="${x}" cy="${y}" r="2.6" fill="${c}" stroke="#fff" stroke-width="1"/>`;
    }).join('');
